// Generate the browser-only slice of the dictionaries.
//
// The host dictionary set is large; the client bundle has a hard 256 KiB limit
// from the DSH client loader, so only the keys the panel can render are shipped
// there. The generated file is committed and checked by `npm run i18n:check`.
import { build } from 'esbuild';
import { execFile } from 'node:child_process';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { promisify } from 'node:util';

const run = promisify(execFile);

const root = fileURLToPath(new URL('../', import.meta.url));
const output = path.join(root, 'src', 'i18n', 'client-strings.ts');

/** Prefixes the browser bundle is allowed to use. */
export const CLIENT_PREFIXES = ['client.', 'ui.', 'permissions.'];

/** Render one filtered dictionary as a TypeScript object literal. */
function render(locale, dictionary) {
  const keys = Object.keys(dictionary)
    .filter((key) => CLIENT_PREFIXES.some((prefix) => key.startsWith(prefix)))
    .sort();
  const lines = keys.map((key) => `    ${JSON.stringify(key)}: ${JSON.stringify(dictionary[key])},`);
  return `  ${JSON.stringify(locale)}: {\n${lines.join('\n')}\n  },`;
}

/** Build the client dictionary source text from the authoritative dictionaries. */
export async function generate() {
  const result = await build({
    absWorkingDir: root,
    stdin: {
      contents: `
        import { en } from './src/i18n/en.ts';
        import { ru } from './src/i18n/ru.ts';
        import { zhCN } from './src/i18n/zh-CN.ts';
        process.stdout.write('@@DICT@@' + JSON.stringify({ en, ru, 'zh-CN': zhCN }));
      `,
      resolveDir: root,
      loader: 'ts',
    },
    bundle: true,
    platform: 'node',
    format: 'esm',
    write: false,
    logLevel: 'silent',
  });
  // The bundle is executed once to emit the dictionaries; nothing is installed.
  const temporary = path.join(os.tmpdir(), `dsh-wsl-client-dict-${process.pid}.mjs`);
  await fs.writeFile(temporary, result.outputFiles[0].text);
  let text;
  try {
    ({ stdout: text } = await run(process.execPath, [temporary], { maxBuffer: 4194304 }));
  } finally {
    await fs.unlink(temporary).catch(() => {});
  }
  const marker = text.lastIndexOf('@@DICT@@');
  if (marker < 0) throw new Error('client dictionary generation produced no payload');
  const dictionaries = JSON.parse(text.slice(marker + '@@DICT@@'.length));
  const body = Object.entries(dictionaries).map(([locale, dictionary]) => render(locale, dictionary)).join('\n');
  return `// Generated by scripts/build-client-dict.mjs — do not edit by hand.
// Only the keys the panel can render are shipped to the browser bundle.
import type { Locale } from './types.js';
import type { MessageKey } from './en.js';

export const CLIENT_DICTIONARIES: Readonly<Record<Locale, Readonly<Partial<Record<MessageKey, string>>>>> = {
${body}
};
`;
}

/** Write the generated file; returns the number of shipped keys. */
export async function write() {
  const source = await generate();
  await fs.writeFile(output, source);
  const keys = (source.match(/":/g) ?? []).length;
  return keys;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === path.resolve(process.argv[1])) {
  const keys = await write();
  console.log(`Client dictionary: ${keys} entries per locale.`);
}
